  --header-doodle-height: 50px;
}

.header-doodle {
  display: block;
  height: var(--header-doodle-height);
  width: auto;
  max-width: min(42vw, 11rem);
  object-fit: cover;
  object-position: center 12%;
  flex-shrink: 0;
  pointer-events: none;
  user-select: none;
}

